const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Mount Vesuvius summit cone location
  const vesuviusCone = ee.Geometry.Point([14.426, 40.821]).buffer(500); // 500m radius around summit
  const startDate = '2022-01-02';
  const endDate = '2022-01-03';

  console.log('Analyzing cloud cover over Mount Vesuvius cone on Jan 2, 2022...');

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(vesuviusCone)
    .filterDate(startDate, endDate);

  const count = collection.size().getInfo();
  console.log(`Landsat 8 images found: ${count}`);

  if (count === 0) {
    // Try Landsat 9 as fallback
    collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(vesuviusCone)
      .filterDate(startDate, endDate);

    const count9 = collection.size().getInfo();
    console.log(`Landsat 9 images found (fallback): ${count9}`);

    if (count9 === 0) {
      console.log('No Landsat data available for this date/location.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Get the image and analyze clouds
  const image = ee.Image(collection.first());
  const qaPixel = image.select('QA_PIXEL');

  // Bit 3 is cloud bit in QA_PIXEL
  const cloudBit = 1 << 3;
  const clouds = qaPixel.bitwiseAnd(cloudBit).neq(0);

  // 4. Calculate statistics
  const stats = clouds.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: vesuviusCone,
    scale: 30,
    maxPixels: 1e9
  });

  const cloudPercentage = stats.get('QA_PIXEL').getInfo();

  if (cloudPercentage === null || cloudPercentage === undefined) {
    console.log('Failed to calculate cloud coverage.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Count total pixels to ensure valid data
  const pixelCount = clouds.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: vesuviusCone,
    scale: 30,
    maxPixels: 1e9
  }).get('QA_PIXEL').getInfo();

  console.log(`Valid pixels analyzed: ${pixelCount}`);
  console.log(`Cloud coverage: ${(cloudPercentage * 100).toFixed(1)}%`);

  if (pixelCount === 0) {
    console.log('No valid pixels in analysis area.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Final Answer
  // Fully covered means 100% or very close to it (>99.5% to account for edge pixels)
  if (cloudPercentage > 0.995) {
    console.log('Mount Vesuvius cone was fully covered with clouds.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Mount Vesuvius cone was NOT fully covered with clouds.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
